-- Apply after the matching Worker release; D1 meta.changes includes trigger writes.
-- Prospective capture only. No historical replay or outbound automation.
CREATE INDEX IF NOT EXISTS idx_cp_events_identity ON audit_log(action,entity_type,entity_id);
CREATE INDEX IF NOT EXISTS idx_cp_events_created ON audit_log(created_at,id);
CREATE INDEX IF NOT EXISTS idx_cp_events_normal_time ON audit_log(replace(substr(created_at,1,19),'T',' '),id);
CREATE INDEX IF NOT EXISTS idx_cp_events_action_id ON audit_log(action,id);
CREATE TRIGGER IF NOT EXISTS cp_evt_content_missionList_created_v1 AFTER UPDATE OF content_json ON app_content WHEN NEW.content_key='club-pop' AND OLD.content_json IS NOT NEW.content_json BEGIN INSERT INTO audit_log(actor_type,actor_id,action,entity_type,entity_id,metadata_json,created_at) SELECT 'SYSTEM',NULL,'cp.content.missionList.created','app_content',json_array('missionList',CAST(json_extract(CASE WHEN n.type='object' THEN n.value ELSE '{}' END,'$.id') AS TEXT)),json_object('unit',COALESCE(json_extract(CASE WHEN n.type='object' THEN n.value ELSE '{}' END,'$.unit'),'club'),'source_table','app_content','operation','created','evo_member_id',json_extract(CASE WHEN n.type='object' THEN n.value ELSE '{}' END,'$.memberId'),'status',json_extract(CASE WHEN n.type='object' THEN n.value ELSE '{}' END,'$.status'),'occurred_at',json_extract(CASE WHEN n.type='object' THEN n.value ELSE '{}' END,'$.createdAt'),'time_basis','source','capture_version','20261027'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM json_each(CASE WHEN json_valid(NEW.content_json) THEN NEW.content_json ELSE '{}' END,'$.missionList') n WHERE json_valid(n.value) AND CAST(json_extract(CASE WHEN n.type='object' THEN n.value ELSE '{}' END,'$.id') AS TEXT) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_valid(OLD.content_json) THEN OLD.content_json ELSE '{}' END,'$.missionList') o WHERE CAST(json_extract(CASE WHEN o.type='object' THEN o.value ELSE '{}' END,'$.id') AS TEXT)=CAST(json_extract(CASE WHEN n.type='object' THEN n.value ELSE '{}' END,'$.id') AS TEXT)); END;
